// TestGeneratePlaintextFixture was used to freeze the fixtureRefPlaintextWALSegment.
// It is disabled now that the fixture is captured.
func TestGeneratePlaintextFixture(t *testing.T) {
	t.Skip("Fixture frozen - this test is disabled")

	tmpDir := t.TempDir()
	w, err := OpenWAL(tmpDir, nil) // Will use current signature until modified
	if err != nil {
		t.Fatalf("OpenWAL: %v", err)
	}
	defer func() { _ = w.Close() }()

	// Append three test entries with predictable data
	testCases := []struct {
		bucket string
		op     byte
		key    []byte
		data   []byte
	}{
		{"test_bucket", OpInsert, []byte("key1"), []byte("value1_data")},
		{"test_bucket", OpUpdate, []byte("key2"), []byte("value2_data_longer")},
		{"test_bucket", OpDelete, []byte("key3"), []byte("")},
	}

	for _, tc := range testCases {
		_, err := w.Append(tc.bucket, tc.op, tc.key, tc.data)
		if err != nil {
			t.Fatalf("Append: %v", err)
		}
	}

	_ = w.Close()

	// Read the segment file and print its hex
	segPath := segmentFilePath(tmpDir, 1)
	segmentBytes, err := os.ReadFile(segPath)
	if err != nil {
		t.Fatalf("ReadFile: %v", err)
	}

	t.Logf("Fixture hex:\n%s", hex.Dump(segmentBytes))
	t.Logf("Fixture len: %d", len(segmentBytes))
	// Also print as a Go byte slice for copying
	t.Logf("As Go bytes:")
	for i := 0; i < len(segmentBytes); i += 16 {
		end := i + 16
		if end > len(segmentBytes) {
			end = len(segmentBytes)
		}
		chunk := segmentBytes[i:end]
		t.Logf("\t%#v,", chunk)
	}
}

// TestSealedWALRoundTrip appends to a sealed WAL, closes it, reopens it and
// reads every entry back whole: the sequence from the clear framing, and the
// operation, bucket, key and data from the sealed body.
func TestSealedWALRoundTrip(t *testing.T) {
	dir := t.TempDir()
	keys := newSealedTestKeySource(t)

	w, err := OpenWAL(dir, keys)
	if err != nil {
		t.Fatalf("OpenWAL: %v", err)
	}

	seqs := make([]uint64, len(sealedTestEntries))
	for i, want := range sealedTestEntries {
		seq, err := w.Append(want.Bucket, want.Op, want.Key, want.Data)
		if err != nil {
			t.Fatalf("Append %d: %v", i, err)
		}
		seqs[i] = seq
	}
	if err := w.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}

	// The file it wrote is a sealed one, so the read below is going through
	// the AEAD and not through some plaintext fallback.
	segmentBytes, err := os.ReadFile(segmentFilePath(dir, 1))
	if err != nil {
		t.Fatalf("reading segment 1: %v", err)
	}
	if !isFileSealedWAL(segmentBytes) {
		t.Fatal("segment 1 is not in the sealed format")
	}

	reopened, err := OpenWAL(dir, keys)
	if err != nil {
		t.Fatalf("OpenWAL after reopen: %v", err)
	}
	defer func() { _ = reopened.Close() }()

	entries, err := reopened.ReadFrom(1)
	if err != nil {
		t.Fatalf("ReadFrom: %v", err)
	}
	if len(entries) != len(sealedTestEntries) {
		t.Fatalf("read %d entries, want %d", len(entries), len(sealedTestEntries))
	}

	for i, got := range entries {
		want := sealedTestEntries[i]
		if got.Seq != seqs[i] {
			t.Errorf("entry %d seq = %d, want %d", i, got.Seq, seqs[i])
		}
		if got.Op != want.Op {
			t.Errorf("entry %d op = %d, want %d", i, got.Op, want.Op)
		}
		if got.Bucket != want.Bucket {
			t.Errorf("entry %d bucket = %q, want %q", i, got.Bucket, want.Bucket)
		}
		if !bytes.Equal(got.Key, want.Key) {
			t.Errorf("entry %d key = %q, want %q", i, got.Key, want.Key)
		}
		if !bytes.Equal(got.Data, want.Data) {
			t.Errorf("entry %d data = %q, want %q", i, got.Data, want.Data)
		}
	}

	// The reopened log continues the sequence rather than restarting it.
	next, err := reopened.Append("bucket1", OpInsert, []byte("k4"), []byte("v4"))
	if err != nil {
		t.Fatalf("Append after reopen: %v", err)
	}
	if next != seqs[len(seqs)-1]+1 {
		t.Errorf("sequence after reopen = %d, want %d", next, seqs[len(seqs)-1]+1)
	}
}

// TestSealCounterRollsTheFile checks the seal counter's only observable effect:
// at sealLimit entries the next append rotates first, so one file key never
// covers more entries than the limit allows.
func TestSealCounterRollsTheFile(t *testing.T) {
	dir := t.TempDir()
	keys := newSealedTestKeySource(t)
	restoreSealLimit(t, 8)

	w, err := OpenWAL(dir, keys)
	if err != nil {
		t.Fatalf("OpenWAL: %v", err)
	}

	for i := 0; i < 8; i++ {
		if _, err := w.Append("bucket1", OpInsert, []byte(fmt.Sprintf("k%d", i)), []byte("v")); err != nil {
			t.Fatalf("append %d: %v", i, err)
		}
	}
	if got := len(w.listSegments()); got != 1 {
		t.Fatalf("after 8 appends: %d segments, want 1 (the limit is not reached until the 9th)", got)
	}

	ninth, err := w.Append("bucket1", OpInsert, []byte("k8"), []byte("v"))
	if err != nil {
		t.Fatalf("ninth append: %v", err)
	}
	if got := len(w.listSegments()); got != 2 {
		t.Fatalf("after the 9th append: %d segments, want 2", got)
	}
	if err := w.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}

	// The new segment carries its own 24-byte header, which is what makes it a
	// new file key rather than a continuation of the old one.
	secondBytes, err := os.ReadFile(segmentFilePath(dir, 2))
	if err != nil {
		t.Fatalf("reading segment 2: %v", err)
	}
	if !isFileSealedWAL(secondBytes) {
		t.Fatal("segment 2 has no sealed header")
	}
	offsets := sealedEntryOffsets(t, secondBytes)
	if len(offsets) != 1 {
		t.Fatalf("segment 2 holds %d entries, want just the 9th", len(offsets))
	}
	if seq := binary.BigEndian.Uint64(secondBytes[offsets[0]+8 : offsets[0]+8+walSeqFieldLen]); seq != ninth {
		t.Errorf("segment 2's first entry has sequence %d, want the 9th append's %d", seq, ninth)
	}

	// Both files still read as one log.
	readSealedWAL(t, dir, keys, 9)
}

// TestTruncateDoesNotDecrypt holds Truncate to N8: retention runs on every
// node, including one that holds no key, and decrypting the whole log to
// decide which files to delete is the thing this format exists to avoid.
func TestTruncateDoesNotDecrypt(t *testing.T) {
	dir := t.TempDir()
	keys := newCountingWALKeySource(t)

	w := openTenSegmentSealedWAL(t, dir, keys)
	defer func() { _ = w.Close() }()

	before := keys.fileKeyCalls
	if err := w.Truncate(5); err != nil {
		t.Fatalf("Truncate: %v", err)
	}
	if got := keys.fileKeyCalls - before; got != 0 {
		t.Errorf("Truncate derived %d file keys, want 0", got)
	}

	// It pruned for real, rather than passing by doing nothing.
	if got := len(w.listSegments()); got != 6 {
		t.Errorf("after Truncate(5): %d segments remain, want 6", got)
	}
}

// TestFirstSequenceReadsOneEntry is the same property on the replication hot
// path: the retention horizon is three reads of clear framing, never a
// decryption.
func TestFirstSequenceReadsOneEntry(t *testing.T) {
	dir := t.TempDir()
	keys := newCountingWALKeySource(t)

	w := openTenSegmentSealedWAL(t, dir, keys)
	defer func() { _ = w.Close() }()

	before := keys.fileKeyCalls
	first, err := w.FirstSequence()
	if err != nil {
		t.Fatalf("FirstSequence: %v", err)
	}
	if got := keys.fileKeyCalls - before; got != 0 {
		t.Errorf("FirstSequence derived %d file keys, want 0", got)
	}
	if first != 1 {
		t.Errorf("first retained sequence = %d, want 1", first)
	}
}

// TestLegacyPlaintextSegmentRotatesRatherThanAppends covers the rollout rule: a
// segment is wholly sealed or wholly plaintext. A keyed open of a log written
// before encryption leaves the old segment exactly as it is — still readable
// for replay, still prunable by retention — and starts a new sealed one. Every
// open starts a new segment (spec §3.4), so this is that rule in the case where
// the key mode changed; TestReopenStartsANewSegmentAndKey is the same mode.
func TestLegacyPlaintextSegmentRotatesRatherThanAppends(t *testing.T) {
	dir := t.TempDir()

	plain, err := OpenWAL(dir, nil)
	if err != nil {
		t.Fatalf("OpenWAL without a key: %v", err)
	}
	for i := 0; i < 2; i++ {
		if _, err := plain.Append("legacy", OpInsert, []byte(fmt.Sprintf("k%d", i)), []byte("v")); err != nil {
			t.Fatalf("plaintext append %d: %v", i, err)
		}
	}
	if err := plain.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	legacyBytes, err := os.ReadFile(segmentFilePath(dir, 1))
	if err != nil {
		t.Fatalf("reading the plaintext segment: %v", err)
	}

	keys := newSealedTestKeySource(t)
	w, err := OpenWAL(dir, keys)
	if err != nil {
		t.Fatalf("OpenWAL with a key over a plaintext segment: %v", err)
	}
	defer func() { _ = w.Close() }()

	if w.activeIndex != 2 {
		t.Errorf("active segment is %d, want 2: the plaintext segment must not be appended to", w.activeIndex)
	}
	if _, err := w.Append("sealed", OpInsert, []byte("k2"), []byte("v")); err != nil {
		t.Fatalf("append after rotation: %v", err)
	}

	// The old segment is byte-for-byte what it was.
	afterBytes, err := os.ReadFile(segmentFilePath(dir, 1))
	if err != nil {
		t.Fatalf("re-reading the plaintext segment: %v", err)
	}
	if !bytes.Equal(afterBytes, legacyBytes) {
		t.Errorf("the plaintext segment changed: %d bytes before, %d after", len(legacyBytes), len(afterBytes))
	}

	// The new one is sealed.
	newBytes, err := os.ReadFile(segmentFilePath(dir, 2))
	if err != nil {
		t.Fatalf("reading the new segment: %v", err)
	}
	if !framesSealed(newBytes) {
		t.Fatal("the new segment is not in the sealed format")
	}

	// The sequence continues across the format boundary rather than restarting.
	if got := w.LastSequence(); got != 3 {
		t.Errorf("last sequence = %d, want 3 (2 plaintext entries then 1 sealed)", got)
	}
}

// openTenSegmentSealedWAL builds a sealed log of ten one-entry segments by
// setting the segment limit just above a single entry.
func openTenSegmentSealedWAL(t *testing.T, dir string, keys WALKeySource) *WAL {
	t.Helper()

	w, err := OpenWAL(dir, keys)
	if err != nil {
		t.Fatalf("OpenWAL: %v", err)
	}
	value := bytes.Repeat([]byte("x"), 64)
	for i := 0; i < 10; i++ {
		if _, err := w.Append("b", OpInsert, []byte(fmt.Sprintf("k%d", i)), value); err != nil {
			t.Fatalf("append %d: %v", i, err)
		}
		// Rotate after every entry so Truncate has whole files to remove, and
		// so ten distinct file keys exist for a decrypting scan to ask for.
		if i < 9 {
			w.mu.Lock()
			err = w.rotate()
			w.mu.Unlock()
			if err != nil {
				t.Fatalf("rotate after append %d: %v", i, err)
			}
		}
	}
	if got := len(w.listSegments()); got != 10 {
		t.Fatalf("built %d segments, want 10", got)
	}
	return w
}

// restoreSealLimit lowers sealLimit for one test and puts it back afterwards.
func restoreSealLimit(t *testing.T, limit int64) {
	t.Helper()
	previous := sealLimit
	sealLimit = limit
	t.Cleanup(func() { sealLimit = previous })
}

// countingWALKeySource counts how many file keys were derived through it.
type countingWALKeySource struct {
	*mockWALKeySource
	fileKeyCalls int
}

func newCountingWALKeySource(t *testing.T) *countingWALKeySource {
	t.Helper()
	return &countingWALKeySource{mockWALKeySource: newSealedTestKeySource(t)}
}

func (c *countingWALKeySource) FileKey(epoch uint64, segIdx int) ([]byte, error) {
	c.fileKeyCalls++
	return c.mockWALKeySource.FileKey(epoch, segIdx)
}

// appendSealedEntries opens a keyed WAL in dir, appends entries, and closes it.
// It returns the raw bytes of segment 1, which is where they all land: the
// default 64 MB segment limit is far above anything these tests write.
func appendSealedEntries(t *testing.T, dir string, keys WALKeySource, entries []WALEntry) []byte {
	t.Helper()

	w, err := OpenWAL(dir, keys)
	if err != nil {
		t.Fatalf("OpenWAL: %v", err)
	}
	for i, e := range entries {
		if _, err := w.Append(e.Bucket, e.Op, e.Key, e.Data); err != nil {
			t.Fatalf("Append %d: %v", i, err)
		}
	}
	if err := w.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}

	segmentBytes, err := os.ReadFile(segmentFilePath(dir, 1))
	if err != nil {
		t.Fatalf("reading segment 1: %v", err)
	}
	return segmentBytes
}

// sealedEntryOffsets walks a sealed segment's clear framing and returns the
// absolute offset of every entry's length word. It uses no key, which is the
// property half these tests are about.
func sealedEntryOffsets(t *testing.T, segmentBytes []byte) []int64 {
	t.Helper()

	if len(segmentBytes) < walFileHeaderLen {
		t.Fatalf("segment is %d bytes, shorter than the %d-byte sealed header", len(segmentBytes), walFileHeaderLen)
	}
	var offsets []int64
	size := int64(len(segmentBytes))
	for offset := int64(walFileHeaderLen); offset < size; {
		if size-offset < 8+walSeqFieldLen {
			t.Fatalf("framing walk hit %d trailing bytes at offset %d", size-offset, offset)
		}
		word := binary.BigEndian.Uint64(segmentBytes[offset : offset+8])
		onDiskLen := int64(uint32(word))
		offsets = append(offsets, offset)
		offset += 8 + walSeqFieldLen + onDiskLen
	}
	return offsets
}

// repairSealedCRC recomputes the CRC of the sealed entry at offset in the v2
// segment segmentBytes, in place, after a test changed its covered bytes.
func repairSealedCRC(t *testing.T, segmentBytes []byte, offset int64) {
	t.Helper()
	format, err := parseWALv2Header(segmentBytes[:walFileHeaderLen])
	if err != nil {
		t.Fatalf("parsing the segment header: %v", err)
	}
	onDiskLen := int64(uint32(binary.BigEndian.Uint64(segmentBytes[offset : offset+8])))
	seqField := segmentBytes[offset+8 : offset+8+walSeqFieldLen]
	payload := segmentBytes[offset+8+walSeqFieldLen : offset+8+walSeqFieldLen+onDiskLen]
	binary.BigEndian.PutUint64(segmentBytes[offset:offset+8], uint64(uint32(onDiskLen))|uint64(format.checksum(seqField, payload))<<32)
}

// sealedTestEntries is the entry set most of these tests append.
var sealedTestEntries = []WALEntry{
	{Bucket: "bucket1", Op: OpInsert, Key: []byte("k1"), Data: []byte("v1")},
	{Bucket: "bucket1", Op: OpUpdate, Key: []byte("k2"), Data: []byte("v2_longer")},
	{Bucket: "bucket2", Op: OpDelete, Key: []byte("k3"), Data: []byte{}},
}

// TestSealedWALFramingIsReadableWithoutAKey verifies that the 24-byte header
// and the sequence number in a sealed WAL entry can be read without decryption.
// This tests the G1 guard: the sequence must be readable before the nonce.
func TestSealedWALFramingIsReadableWithoutAKey(t *testing.T) {
	dir := t.TempDir()
	segmentBytes := appendSealedEntries(t, dir, newSealedTestKeySource(t), sealedTestEntries[:1])

	// Everything below reads the file and nothing else. No key is in scope.
	// The segment is format 2: its header is the WAL's own (spec §3.1), sealed
	// in flag 0x02, with a non-zero generation.
	fileHeader, err := parseWALv2Header(segmentBytes[:walFileHeaderLen])
	if err != nil {
		t.Fatalf("the 24-byte segment header must parse without a key: %v", err)
	}
	if !fileHeader.sealed {
		t.Error("the header of a keyed segment does not say its entries are sealed")
	}
	if fileHeader.epochID != 1 {
		t.Errorf("header epoch = %d, want 1", fileHeader.epochID)
	}
	if fileHeader.gen == 0 {
		t.Error("header gen = 0, want the segment's generation")
	}

	word := binary.BigEndian.Uint64(segmentBytes[walFileHeaderLen : walFileHeaderLen+8])
	onDiskLen := int64(uint32(word))
	crc := uint32(word >> 32)

	// The sequence sits between the length word and the nonce: readable before
	// any byte that needs a key. Omit it from the framing and this offset holds
	// the nonce instead, so the read below returns nonsense.
	seqOffset := int64(walFileHeaderLen + 8)
	seq := binary.BigEndian.Uint64(segmentBytes[seqOffset : seqOffset+walSeqFieldLen])
	if seq != 1 {
		t.Errorf("first entry's clear sequence = %d, want 1", seq)
	}

	if onDiskLen < walSealedMinOnDisk {
		t.Errorf("on-disk length %d is below the %d-byte minimum", onDiskLen, walSealedMinOnDisk)
	}
	wantSize := int64(walFileHeaderLen) + 8 + walSeqFieldLen + onDiskLen
	if int64(len(segmentBytes)) != wantSize {
		t.Errorf("segment is %d bytes, want %d from the framing arithmetic", len(segmentBytes), wantSize)
	}

	// The CRC covers the generation, the clear sequence and the on-disk bytes
	// (nonce, ciphertext, tag), all in the clear, which is what lets
	// the open cut a torn tail with no key at all.
	payload := segmentBytes[seqOffset+walSeqFieldLen:]
	var covered []byte
	covered = append(covered, segmentBytes[16:24]...)
	covered = append(covered, segmentBytes[seqOffset:seqOffset+walSeqFieldLen]...)
	covered = append(covered, payload...)
	if got := crc32.Checksum(covered, crc32cTable); got != crc {
		t.Errorf("CRC over gen || seq || on-disk bytes = %08x, framing says %08x", got, crc)
	}
}

// TestWALEntryAADBindsSequence verifies that changing the clear sequence number
// makes the AEAD decryption fail.
func TestWALEntryAADBindsSequence(t *testing.T) {
	dir := t.TempDir()
	keys := newSealedTestKeySource(t)
	segmentBytes := appendSealedEntries(t, dir, keys, sealedTestEntries)

	// Control: untouched, the log reads back.
	readSealedWAL(t, dir, keys, len(sealedTestEntries))

	// Rewrite the first entry's clear sequence, and the CRC with it: in format
	// 2 the CRC covers the sequence, so without the repair the entry would read
	// as a torn tail. Repaired, the framing checks out and only the AAD has
	// moved.
	seqOffset := int64(walFileHeaderLen + 8)
	tampered := append([]byte(nil), segmentBytes...)
	binary.BigEndian.PutUint64(tampered[seqOffset:seqOffset+walSeqFieldLen], 99)
	repairSealedCRC(t, tampered, walFileHeaderLen)
	writeSegment(t, dir, tampered)

	_, err := OpenWAL(dir, keys)
	if err == nil {
		t.Fatal("a rewritten clear sequence must fail the entry's AEAD, but the log opened")
	}
	if !strings.Contains(err.Error(), "wal_00001.log") {
		t.Errorf("the error must name the segment, got: %v", err)
	}
}

// TestWALEntryAADBindsOffset verifies that copying a sealed entry to a different
// offset in the file makes the AEAD decryption fail (offset is part of AAD).
func TestWALEntryAADBindsOffset(t *testing.T) {
	dir := t.TempDir()
	keys := newSealedTestKeySource(t)
	segmentBytes := appendSealedEntries(t, dir, keys, sealedTestEntries[:2])

	// Move the second entry, byte for byte, to where the first one was. Its
	// sequence, nonce, ciphertext and CRC are all unchanged and its sequence
	// still rises (a copy of an entry after itself would not, and would read
	// as the end of the log before the AEAD), so the single thing that changed
	// is its offset.
	offsets := sealedEntryOffsets(t, segmentBytes)
	copyOffset := int64(walFileHeaderLen)
	tampered := append(append([]byte(nil), segmentBytes[:walFileHeaderLen]...), segmentBytes[offsets[1]:]...)
	writeSegment(t, dir, tampered)

	_, err := OpenWAL(dir, keys)
	if err == nil {
		t.Fatal("an entry moved to another offset must fail its AEAD, but the log opened")
	}
	// The first copy, at its original offset, still opens — so the failure the
	// scan reports is the relocated one and nothing else.
	if !strings.Contains(err.Error(), fmt.Sprintf("offset %d", copyOffset)) {
		t.Errorf("the error must name offset %d (the relocated copy), got: %v", copyOffset, err)
	}
}

// TestWALEpochSwapRefuses verifies that editing the epoch ID in the 24-byte
// file header makes every entry's decryption fail (epoch is part of AAD).
func TestWALEpochSwapRefuses(t *testing.T) {
	dir := t.TempDir()
	// This key source hands back the same epoch key whatever epoch is asked
	// for, so a swapped epoch id changes the AAD and nothing else. Without
	// that, the swap would fail at key lookup and prove nothing about the AAD.
	keys := newSealedTestKeySource(t)
	keys.acceptAnyEpoch = true
	segmentBytes := appendSealedEntries(t, dir, keys, sealedTestEntries)

	readSealedWAL(t, dir, keys, len(sealedTestEntries))

	tampered := append([]byte(nil), segmentBytes...)
	binary.BigEndian.PutUint64(tampered[8:16], 2)
	writeSegment(t, dir, tampered)

	// The framing is untouched: a keyless walk still finds all three entries
	// and no torn tail. So whatever fails below is cryptographic.
	offsets := sealedEntryOffsets(t, tampered)
	if len(offsets) != len(sealedTestEntries) {
		t.Fatalf("framing walk found %d entries, want %d", len(offsets), len(sealedTestEntries))
	}

	_, err := OpenWAL(dir, keys)
	if err == nil {
		t.Fatal("a swapped epoch id must fail every entry, but the log opened")
	}
	if !strings.Contains(err.Error(), "epoch 2") {
		t.Errorf("the error must name the epoch it tried, got: %v", err)
	}
	// The scan refuses at the first entry, so no entry survives the swap.
	if !strings.Contains(err.Error(), fmt.Sprintf("offset %d", offsets[0])) {
		t.Errorf("the error must name the first entry's offset %d, got: %v", offsets[0], err)
	}
}

// TestSealedWALTornTailRepairsWithoutAKey verifies that torn tail repair works
// without a key source (the CRC and length are in the clear).
func TestSealedWALTornTailRepairsWithoutAKey(t *testing.T) {
	dir := t.TempDir()
	segmentBytes := appendSealedEntries(t, dir, newSealedTestKeySource(t), sealedTestEntries)

	offsets := sealedEntryOffsets(t, segmentBytes)
	if len(offsets) != len(sealedTestEntries) {
		t.Fatalf("framing walk found %d entries, want %d", len(offsets), len(sealedTestEntries))
	}
	lastOffset := offsets[len(offsets)-1]

	// Cut the last entry in half, the shape a crash or a full disk leaves.
	torn := append([]byte(nil), segmentBytes[:lastOffset+8]...)
	writeSegment(t, dir, torn)

	// No key source at all: repair is framing arithmetic and a CRC, both clear.
	w, err := OpenWAL(dir, nil)
	if err != nil {
		t.Fatalf("a torn sealed tail must be repaired without a key, got: %v", err)
	}
	defer func() { _ = w.Close() }()

	recovery := w.Recovery()
	if recovery == nil {
		t.Fatal("a torn tail must be reported in Recovery(), got nil")
	}
	if recovery.RecoveredTo != lastOffset {
		t.Errorf("recovered to offset %d, want %d (the start of the torn entry)", recovery.RecoveredTo, lastOffset)
	}
	if recovery.DroppedBytes != 8 {
		t.Errorf("dropped %d bytes, want 8", recovery.DroppedBytes)
	}

	info, err := os.Stat(segmentFilePath(dir, 1))
	if err != nil {
		t.Fatalf("stat repaired segment: %v", err)
	}
	if info.Size() != lastOffset {
		t.Errorf("repaired segment is %d bytes, want %d", info.Size(), lastOffset)
	}
}

// TestCRCPassesButOpenFailsIsCorruption verifies that when the CRC passes but
// the AEAD Open fails, the error is reported as corruption, not skipped.
// This is trap 2's guard.
func TestCRCPassesButOpenFailsIsCorruption(t *testing.T) {
	dir := t.TempDir()
	keys := newSealedTestKeySource(t)
	segmentBytes := appendSealedEntries(t, dir, keys, sealedTestEntries)

	offsets := sealedEntryOffsets(t, segmentBytes)
	firstOffset := offsets[0]
	payloadOffset := firstOffset + 8 + walSeqFieldLen

	// Flip a ciphertext bit, then repair the CRC over the new bytes (in format
	// 2: gen || seq || on-disk bytes), so the framing check the torn-tail path
	// relies on passes and only the tag disagrees. Nothing but the AEAD can
	// catch this.
	tampered := append([]byte(nil), segmentBytes...)
	tampered[payloadOffset+walNonceLen] ^= 0x01
	repairSealedCRC(t, tampered, firstOffset)
	writeSegment(t, dir, tampered)

	_, err := OpenWAL(dir, keys)
	if err == nil {
		t.Fatal("an entry whose CRC passes and whose AEAD fails is corruption, but the log opened")
	}
	if !strings.Contains(err.Error(), fmt.Sprintf("offset %d", firstOffset)) {
		t.Errorf("the corruption error must name the entry's offset %d, got: %v", firstOffset, err)
	}

	// Corruption is reported, never skipped: the entry is not truncated away as
	// if it were a torn tail, so the file still holds all three entries.
	info, err := os.Stat(segmentFilePath(dir, 1))
	if err != nil {
		t.Fatalf("stat segment after the refused open: %v", err)
	}
	if info.Size() != int64(len(tampered)) {
		t.Errorf("segment was truncated to %d bytes: corruption was treated as a torn tail", info.Size())
	}
}

// TestSealedWALNeverWritesPlaintextBody is the critical guard against forgetting
// to seal on the write path. It appends an entry with a recognizable marker
// and searches the raw segment file for that marker - if found, sealing was skipped.
// This is the only test that catches a write-path AEAD skip.
func TestSealedWALNeverWritesPlaintextBody(t *testing.T) {
	dir := t.TempDir()
	const (
		bucketMarker = "bucketmarker_5f2ac9d1"
		keyMarker    = "keymarker_71bd0e34"
		dataMarker   = "datamarker_c8e4a6b2"
	)
	segmentBytes := appendSealedEntries(t, dir, newSealedTestKeySource(t), []WALEntry{
		{Bucket: bucketMarker, Op: OpInsert, Key: []byte(keyMarker), Data: []byte(dataMarker)},
	})

	// Guard the guard: if the segment were not sealed at all this search would
	// pass on a file that never held a body to begin with.
	if !isFileSealedWAL(segmentBytes) {
		t.Fatal("segment 1 is not in the sealed format, so this test proves nothing")
	}

	for _, marker := range []string{bucketMarker, keyMarker, dataMarker} {
		if bytes.Contains(segmentBytes, []byte(marker)) {
			t.Errorf("%q appears in the raw segment: the write path skipped the AEAD", marker)
		}
	}

	// Positive control: the same entry through an unkeyed WAL must show every
	// marker to the same scan, otherwise the absence above proves nothing. WAL
	// segments are not compressed, so a marker is contiguous on disk; the scan
	// still uses the interior, as the Badger-side scan does.
	plaintextBytes := appendSealedEntries(t, t.TempDir(), nil, []WALEntry{
		{Bucket: bucketMarker, Op: OpInsert, Key: []byte(keyMarker), Data: []byte(dataMarker)},
	})
	for _, marker := range []string{bucketMarker, keyMarker, dataMarker} {
		if !bytes.Contains(plaintextBytes, []byte(marker[2:len(marker)-2])) {
			t.Errorf("%q is not in a plaintext WAL segment: the scan cannot see what it looks for", marker)
		}
	}
}

// readSealedWAL reopens a keyed WAL and asserts it reads back want entries.
func readSealedWAL(t *testing.T, dir string, keys WALKeySource, want int) {
	t.Helper()

	w, err := OpenWAL(dir, keys)
	if err != nil {
		t.Fatalf("reopening the sealed WAL: %v", err)
	}
	defer func() { _ = w.Close() }()

	entries, err := w.ReadFrom(1)
	if err != nil {
		t.Fatalf("ReadFrom: %v", err)
	}
	if len(entries) != want {
		t.Fatalf("read %d entries, want %d", len(entries), want)
	}
	for i, e := range entries {
		if e.Seq != uint64(i+1) {
			t.Errorf("entry %d has seq %d, want %d", i, e.Seq, i+1)
		}
	}
}

// writeSegment replaces segment 1's bytes wholesale.
func writeSegment(t *testing.T, dir string, segmentBytes []byte) {
	t.Helper()
	if err := os.WriteFile(segmentFilePath(dir, 1), segmentBytes, 0o644); err != nil {
		t.Fatalf("rewriting segment 1: %v", err)
	}
}

// newSealedTestKeySource builds a key source over a random epoch key at epoch 1.
func newSealedTestKeySource(t *testing.T) *mockWALKeySource {
	t.Helper()
	keys := &mockWALKeySource{currentEpoch: 1, epochKey: make([]byte, 32)}
	if _, err := rand.Read(keys.epochKey); err != nil {
		t.Fatalf("generating a test epoch key: %v", err)
	}
	return keys
}

// fixtureRefPlaintextV2WALSegment is the plain segment format 2 holds for the
// three entries of fixtureRefPlaintextWALSegment, with the generation fixed at
// frozenWALGeneration: the 24-byte header (flags 0x01, epoch 0), then each
// entry with its CRC32C taken over gen || body (spec §3.1, §3.2). It was
// computed from the spec's layout by a separate CRC32C implementation, not
// captured from the writer, and it is frozen: changing a byte is a change to an
// on-disk format nodes have written.
var fixtureRefPlaintextV2WALSegment = mustDecodeHex(
	"004844420204010000000000000000000123456789abcdef" +
		"6e181a520000002b0000000000000001000000000b746573745f6275636b6574000000046b65793176616c7565315f64617461" +
		"c08b59b2000000320000000000000002020000000b746573745f6275636b6574000000046b65793276616c7565325f646174615f6c6f6e676572" +
		"1426acc3000000200000000000000003010000000b746573745f6275636b6574000000046b657933")

// mustDecodeHex decodes a frozen hex literal; a bad literal is a bug in the
// test file itself, found the first time the package's tests run.
func mustDecodeHex(literal string) []byte {
	decoded, err := hex.DecodeString(literal)
	if err != nil {
		panic(fmt.Sprintf("a frozen hex literal does not decode: %v", err))
	}
	return decoded
}

// TestNilKeySourcePlainV2Fixture: with a nil key source the log writes exactly
// the frozen v2 plain segment for the fixture's three entries, given the fixed
// generation. It replaces TestNilKeySourceIsByteIdenticalToToday, whose v1
// fixture TestWALReadsV1Segments now reads. Break by: any change to the
// header layout, the flags, or what the CRC covers.
func TestNilKeySourcePlainV2Fixture(t *testing.T) {
	fixWALGeneration(t, frozenWALGeneration)
	dir := t.TempDir()
	w, err := OpenWAL(dir, nil)
	if err != nil {
		t.Fatalf("OpenWAL: %v", err)
	}
	for _, tc := range []struct {
		op        byte
		key, data string
	}{{OpInsert, "key1", "value1_data"}, {OpUpdate, "key2", "value2_data_longer"}, {OpDelete, "key3", ""}} {
		if _, err := w.Append("test_bucket", tc.op, []byte(tc.key), []byte(tc.data)); err != nil {
			t.Fatalf("Append: %v", err)
		}
	}
	if err := w.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	got, err := os.ReadFile(segmentFilePath(dir, 1))
	if err != nil {
		t.Fatalf("reading the segment: %v", err)
	}
	if !bytes.Equal(got, fixtureRefPlaintextV2WALSegment) {
		t.Fatalf("the plain v2 segment differs from the frozen fixture\n got % x\nwant % x", got, fixtureRefPlaintextV2WALSegment)
	}
}

// frozenWALGeneration is the generation the frozen v2 bytes (the plain
// fixture, the origin vectors) were computed with.
const frozenWALGeneration uint64 = 0x0123456789abcdef

// fixWALGeneration makes every segment born during the test take gen, and
// restores the random generation after it.
func fixWALGeneration(t *testing.T, gen uint64) {
	t.Helper()
	previous := walGeneration
	walGeneration = func() uint64 { return gen }
	t.Cleanup(func() { walGeneration = previous })
}

// mockWALKeySource implements WALKeySource for testing.
//
// acceptAnyEpoch makes it serve the same epoch key under every epoch id. That
// is what lets TestWALEpochSwapRefuses isolate the AAD: with the default
// behaviour a swapped epoch id fails at the key lookup, which would pass even
// if the file header were left out of the AAD entirely.
type mockWALKeySource struct {
	currentEpoch   uint64
	epochKey       []byte
	acceptAnyEpoch bool
}

func (m *mockWALKeySource) CurrentEpoch() uint64 {
	return m.currentEpoch
}

func (m *mockWALKeySource) FileKey(epoch uint64, segIdx int) ([]byte, error) {
	if epoch != m.currentEpoch && !m.acceptAnyEpoch {
		return nil, fmt.Errorf("epoch %d not found", epoch)
	}
	// Derive the file key using sealed.FileKey
	identity := fmt.Sprintf("wal/%d", segIdx)
	return sealed.FileKey(m.epochKey, sealed.PurposeWALEntry, identity)
}
